"""Collect pinned config/code/issue evidence without downloading model weights or corpora."""
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
import requests,json,hashlib,subprocess
ROOT=Path(__file__).resolve().parents[1];REF=ROOT/'references/marin/2026-marin-replication-code-audit';REF.mkdir(exist_ok=True)
def get_issue(n):
 u=f'https://api.github.com/repos/marin-community/marin/issues/{n}';r=requests.get(u,timeout=45);r.raise_for_status();d=r.json();(REF/f'issue-{n}.json').write_text(json.dumps(d,indent=2)+'\n')
 comments=[]
 for page in range(1,11):
  r=requests.get(u+f'/comments?per_page=100&page={page}',timeout=45);r.raise_for_status();c=r.json();comments+=c
  if len(c)<100:break
 (REF/f'issue-{n}-comments.json').write_text(json.dumps(comments,indent=2)+'\n');(REF/f'issue-{n}.md').write_text(f'# {d["title"]}\n\nSource: {d["html_url"]}\n\n'+(d.get('body') or '')+'\n\n'+'\n\n'.join(f'## Comment {x["id"]} ({x["created_at"]})\n\n{x.get("body") or ""}' for x in comments))
 return {'number':n,'title':d['title'],'comments':len(comments),'url':d['html_url']}
def get_model(repo):
 r=requests.get('https://huggingface.co/api/models/'+repo,timeout=30);r.raise_for_status();sha=r.json()['sha'];url=f'https://huggingface.co/{repo}/resolve/{sha}/config.json';r=requests.get(url,timeout=30);r.raise_for_status();name=repo.replace('/','--')+'.json';(REF/name).write_bytes(r.content);return {'repository':repo,'revision':sha,'file':name,'url':url}
def main():
 issues=list(ThreadPoolExecutor(3).map(get_issue,[5951,7856,8003]));models=list(ThreadPoolExecutor(3).map(get_model,['Qwen/Qwen3-30B-A3B','Qwen/Qwen3-235B-A22B','allenai/OLMoE-1B-7B-0924']))
 repo=ROOT/'tmp/marin';sha=subprocess.check_output(['git','-C',str(repo),'rev-parse','HEAD'],text=True).strip();paths=['experiments/grug/moe_hero_ep/launch_h100_scaling_ladder.py','experiments/references/reference_hyperparameter_sweep.py','experiments/references/completed_adamh.py','experiments/grug/moe/heuristic.py','experiments/grug/moe_hero_ep/heuristic.py','experiments/grug/moe_hero_ep/hero_recipe.py','experiments/grug/moe_hero_ep/launch_scaling_ladder.py','experiments/grug/moe_hero_ep/small_scale_abl_launch.py','experiments/grug/moe_hero_ep/model.py','experiments/grug/moe_hero_ep/optimizer.py','experiments/grug/moe_hero_ep/harrier_mix_2026_08_18.py','experiments/grug/moe_hero_ep/harrier_mix_2026_08_18.json','experiments/datakit/reference_pipeline.py','experiments/datakit/README.md','lib/marin/src/marin/datakit/sources.py','lib/marin/src/marin/datakit/normalize.py','lib/marin/src/marin/datakit/decon.py','experiments/datakit/global_exact_dedup.py','experiments/datakit/store/datakit_store.py','experiments/datakit/embeddings/luxical/pipeline.py','experiments/datakit/cluster/quality/fast_transformer/bucket.py','experiments/datakit/cluster/quality/fast_transformer/quality_model.py','experiments/datakit/cluster/quality/fast_transformer/artifact.py','experiments/datakit/cluster/quality/fast_transformer/rubric.py','experiments/datakit/scripts/trigger_sources.py','experiments/datakit/cluster/domain/v0/assign.py','experiments/datakit/cluster/domain/v0/train.py','experiments/datakit/cluster/quality/fast_transformer/score.py','experiments/datakit/cluster/quality/fast_transformer/train.py','experiments/datakit/cluster/quality/fast_transformer/README.md','experiments/datakit/cluster/quality/fast_transformer/calibrate.py','experiments/datakit/scripts/fuzzy_cluster_verify.py','experiments/datakit/store/bucket_writer.py','lib/marin/src/marin/processing/classification/deduplication/cluster_verify.py','lib/marin/src/marin/processing/classification/deduplication/cluster_dedup.py']
 files=[]
 for name in paths:
  src=repo/name;p=REF/'code'/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(src.read_bytes());files.append({'path':'code/'+name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'url':f'https://github.com/marin-community/marin/blob/{sha}/{name}'})
 archive=REF/'repository.tar.gz';subprocess.run(['git','-C',str(repo),'archive','--format=tar.gz','--output='+str(archive),sha],check=True)
 snapshot={'date':'2026-11-02','marin_revision':sha,'issues':issues,'models':models,'files':files,'complete_tracked_tree':{'path':'repository.tar.gz','revision':sha,'sha256':hashlib.sha256(archive.read_bytes()).hexdigest(),'note':'Tracked tree only; external data/checkpoints are not included.'}};(REF/'audit.json').write_text(json.dumps(snapshot,indent=2)+'\n');(REF/'metadata.json').write_text(json.dumps({'title':'Marin replication code audit: optimizer searches, MoE ladder and Datakit','topic':'marin','url':f'https://github.com/marin-community/marin/tree/{sha}','retrieved_at':'2026-11-02','revision':sha,'artifact':'audit.json','code':[{'repository':'https://github.com/marin-community/marin','revision':sha,'status':'downloaded','archive':'repository.tar.gz','bytes':archive.stat().st_size,'role':'complete pinned tracked tree for replication audit; external data/checkpoints not included'}]},indent=2)+'\n');(REF/'README.md').write_text('# Marin replication evidence\n\nSee [audit.json](audit.json) for pinned code/model config files and issue snapshots. These are evidence, not a complete prepared corpus or executed training reproduction.\n');print(json.dumps({'issues':issues,'models':models,'code_files':len(files)},indent=2))
if __name__=='__main__':main()
